class _Flow extends StatelessWidget{final List<String> steps;const _Flow({required this.steps});@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('Semplice, trasparente, dinamico.',style:TextStyle(fontSize:22,fontWeight:FontWeight.w900)),const SizedBox(height:12),for(int i=0;i<steps.length;i++)Padding(padding:const EdgeInsets.only(bottom:8),child:GlassCard(glow:i==1,child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[CircleAvatar(backgroundColor:MercDealTheme.green,foregroundColor:Colors.black,radius:15,child:Text('${i+1}',style:const TextStyle(fontWeight:FontWeight.w900))),const SizedBox(width:11),Expanded(child:Text(steps[i],style:const TextStyle(fontWeight:FontWeight.w700,height:1.35)))]))),const SizedBox(height:6),const GlassCard(glow:true,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('📉 Asta al ribasso',style:TextStyle(fontSize:19,fontWeight:FontWeight.w900)),SizedBox(height:6),Text('€500 ↓ €5 → €495 ↓ €5 → €490 … fino al prezzo minimo. Il minimo resta protetto e non viene mostrato agli altri utenti.',style:TextStyle(color:Colors.white70,height:1.4)),SizedBox(height:7),Text('Asta al ribasso = maggiore esposizione gratuita, non garanzia di vendita.',style:TextStyle(color:MercDealTheme.green,fontWeight:FontWeight.w800,fontSize:11))]))]);}
